"""specs_s200045.py - Sonnet-w2 family W (generated by mkfamW.py): the callees record the SEH chain and the object's vtable word; fake outer SEH records 0-2; fs:[0] compared; flags cover the low bits."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _mk(c1):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        o = rnd(c, 0x80)
        hook_rec(c, c1, 0, ret=r.getrandbits(32), this=True, side=_side(c, o))
        hook_rec(c, 0x43de70, 0, ret=r.getrandbits(32), this=True, side=_side(c, o))
        hook_rec(c, 0x4690b0, 2, ret=r.getrandbits(32), pop=0, side=_side(c, o))
        hook_rec(c, 0x45c510, 1, ret=r.getrandbits(32), pop=0, side=_side(c, o))
        return [o, r.choice([0, 1, 2, 3, 4, 5, 6, 7, 0x100, 0xffffffff, r.getrandbits(32)])]
    return gen


S(0x4ee5b0, 'GUESS famW 0x4ee5b0', 'thiscall', None, ret='eax', gen=_mk(0x4f0c10), note='batch200045')
S(0x44b790, 'GUESS famW 0x44b790', 'thiscall', None, ret='eax', gen=_mk(0x44c060), note='batch200045')
